import java.nio.file.*;import java.time.*;import java.time.format.*;import java.util.*;import java.util.stream.*;import java.util.concurrent.atomic.*;
public class ExamEngine{public static void main(String[]a)throws Exception{Scanner s=new Scanner(System.in);System.out.println("Please enter your name");String n=s.nextLine().toLowerCase();String[]r={n+"\r\n"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("MM/dd/yyyy HH:mm:ss"))+"\r\nCorrect Words:\r\n"};AtomicInteger c=new AtomicInteger();List<String>w=Files.readAllLines(Paths.get("words.txt")),d=Files.readAllLines(Paths.get("defs.txt"));IntStream.range(0,w.size()).boxed().collect(Collectors.collectingAndThen(Collectors.toList(),l->{Collections.shuffle(l);return l.stream();})).peek(i->System.out.println(d.get(i)+i)).forEach(i->{if(s.nextLine().equalsIgnoreCase(w.get(i))){System.out.println("Correct!\n");r[0]+=w.get(i)+"\r\n";c.incrementAndGet();}else System.out.println("Incorrect.\n");});Files.write(Paths.get(n+".txt"),r[0].getBytes());System.out.println(n+" your score was "+c+" of "+w.size()+"!");}}
